import{_ as t,o as e,c as a,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-05-14","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-05-14","date":"2025-05-14T00:00:00.000Z","updated":"2025-05-24T00:00:00.000Z","tags":["Ceph","RGW","分布式存储","API","调优"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-05-14.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-05-14.md","lastUpdated":1780460162000}'),r={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-05-14.md"};function n(s,o,l,g,c,d){return e(),a("div",null,[...o[0]||(o[0]=[i('<h3 id="ceph-rgw-重构会议纪要" tabindex="-1">Ceph RGW 重构会议纪要 <a class="header-anchor" href="#ceph-rgw-重构会议纪要" aria-label="Permalink to &quot;Ceph RGW 重构会议纪要&quot;">​</a></h3><p><strong>会议日期</strong>: 2025-05-14<br><strong>参会人员</strong>: 待补充<br><strong>讨论主题</strong>: RGW (RADOS Gateway) 相关功能设计与实现</p><h4 id="_1-bucket-logging-api-实现位置讨论" tabindex="-1">1. Bucket Logging API 实现位置讨论 <a class="header-anchor" href="#_1-bucket-logging-api-实现位置讨论" aria-label="Permalink to &quot;1. Bucket Logging API 实现位置讨论&quot;">​</a></h4><ul><li><strong>问题背景</strong>: 需要为 <code>bucket logging</code> 添加一个返回规范化操作名称的 API，以匹配 AWS 日志中的命名格式。</li><li><strong>关键讨论点</strong>: RGW 操作类存在三层抽象，包括 S3/Swift 协议层、Object Store 层和基础操作类。</li><li><strong>决策</strong>: 将实现放在 <code>RGWOp_ObjectStore</code> 层，以记录 S3/Swift 操作；对于非 REST 操作，放在基类 <code>RGWOp</code> 中；默认实现返回操作名称，子类可覆盖以匹配 AWS 格式。</li><li><strong>后续行动</strong>: 在 <code>RGWOp_ObjectStore</code> 中实现 API。</li></ul><h4 id="_2-持久化通知-persistent-notifications-的存储池选择问题" tabindex="-1">2. 持久化通知（Persistent Notifications）的存储池选择问题 <a class="header-anchor" href="#_2-持久化通知-persistent-notifications-的存储池选择问题" aria-label="Permalink to &quot;2. 持久化通知（Persistent Notifications）的存储池选择问题&quot;">​</a></h4><ul><li><strong>问题背景</strong>: 当前的持久化通知队列对象默认存储在 <code>log pool</code>，但可能导致性能问题。</li><li><strong>解决方案讨论</strong>: 允许通过 <code>zone params</code> 指定自定义池（如 <code>notif_pool</code>），但需处理迁移问题。</li><li><strong>后续行动</strong>: 默认使用 <code>log pool</code>，但提供配置选项；补充文档说明性能建议和迁移步骤。</li></ul><h4 id="_3-cors-全局规则支持-dashboard-团队需求" tabindex="-1">3. CORS 全局规则支持（Dashboard 团队需求） <a class="header-anchor" href="#_3-cors-全局规则支持-dashboard-团队需求" aria-label="Permalink to &quot;3. CORS 全局规则支持（Dashboard 团队需求）&quot;">​</a></h4><ul><li><strong>问题背景</strong>: Dashboard 团队在测试 S3 浏览器应用时，因 CORS 限制导致交互失败。</li><li><strong>需求</strong>: 扩展 RGW 的 CORS 支持，添加全局规则以简化 S3 浏览器集成。</li><li><strong>后续行动</strong>: 跟踪相关 Issue，协调开发资源。</li></ul><h4 id="_4-快照-snapshot-统计数据的处理逻辑" tabindex="-1">4. 快照（Snapshot）统计数据的处理逻辑 <a class="header-anchor" href="#_4-快照-snapshot-统计数据的处理逻辑" aria-label="Permalink to &quot;4. 快照（Snapshot）统计数据的处理逻辑&quot;">​</a></h4><ul><li><strong>问题背景</strong>: <code>head bucket</code> 返回的统计信息是否应包含快照中的隐藏对象。</li><li><strong>决策</strong>: 对外 API 返回当前视图，内部接口返回全量数据（含快照）。</li><li><strong>后续行动</strong>: 明确快照统计逻辑并更新相关接口。</li></ul><h4 id="_5-其他事项" tabindex="-1">5. 其他事项 <a class="header-anchor" href="#_5-其他事项" aria-label="Permalink to &quot;5. 其他事项&quot;">​</a></h4><ul><li><strong>Tentacle 版本状态</strong>: 仍处于代码冻结阶段，等待 RC 发布。</li><li><strong>文档改进</strong>: 需补充各存储池的性能特性说明。</li></ul><p><strong>下一步行动</strong></p><ol><li>实现 <code>bucket logging</code> API 并提交代码审核。</li><li>完善 <code>notif_pool</code> 配置及迁移文档。</li><li>推进 CORS 全局规则开发。</li><li>明确快照统计逻辑并更新相关接口。</li></ol>',14)])])}const p=t(r,[["render",n]]);export{_ as __pageData,p as default};
